export const Playground: StoryObj<{
  side: "top" | "right" | "bottom" | "left";
  showCloseButton: boolean;
  defaultOpen: boolean;
}> = {
  argTypes: {
    defaultOpen: { control: "boolean" },
    showCloseButton: { control: "boolean" },
    side: { control: "select", options: ["top", "right", "bottom", "left"] },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import {
  Sheet,
  SheetTrigger,
  SheetPanel,
  SheetHeader,
  SheetContent,
  SheetTitle,
  SheetDescription,
} from "@/registry/erbium/ui/sheet";
import { Button } from "@/registry/erbium/ui/button";

export const defaultProps = { defaultOpen: false, showCloseButton: true, side: "right" } satisfies {
  side: "top" | "right" | "bottom" | "left";
  showCloseButton: boolean;
  defaultOpen: boolean;
};

export default function SheetPlaygroundExample(
  args: {
    side: "top" | "right" | "bottom" | "left";
    showCloseButton: boolean;
    defaultOpen: boolean;
  } = defaultProps,
) {
  return (
    <Sheet key={String(args.defaultOpen)} defaultOpen={args.defaultOpen}>
      <SheetTrigger render={<Button variant="outline">Open sheet</Button>} />
      <SheetPanel side={args.side} showCloseButton={args.showCloseButton}>
        <SheetHeader>
          <SheetTitle>Sheet title</SheetTitle>
          <SheetDescription>Sheet description.</SheetDescription>
        </SheetHeader>
        <SheetContent>Sheet content.</SheetContent>
      </SheetPanel>
    </Sheet>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

